// src/components/JobItem.jsx
import React, { useState } from "react";
import "./JobItem.css";

const JobItem = ({ job, deleteJob, updateStatus }) => {
  const [newStatus, setNewStatus] = useState(job.status);

  const handleUpdate = () => {
    updateStatus(job._id, newStatus);
  };

  return (
    <div className="job-card">
      <h3>{job.company}</h3>
      <p><strong>Role:</strong> {job.role}</p>
      <p><strong>Date:</strong> {new Date(job.date).toLocaleDateString()}</p>
      <p><strong>Link:</strong> <a href={job.link} target="_blank" rel="noreferrer">View</a></p>

      <div className="status-bar">
        <select value={newStatus} onChange={(e) => setNewStatus(e.target.value)}>
          <option>Applied</option>
          <option>Interview</option>
          <option>Offer</option>
          <option>Rejected</option>
        </select>
        <button onClick={handleUpdate}>Update</button>
        <button onClick={() => deleteJob(job._id)}>Delete</button>
      </div>
    </div>
  );
};

export default JobItem;
